# -*- coding: utf-8 -*-
"""YOUBIN SAMIUL — Railway-safe build (file1 match/EXP logic).

Match end: cmd 103/107 + idle 15s (file1)
EXP refresh retries kept
Startup prints full traceback on crash (so Railway logs show the real error)
"""
import base64
import json
import os
import sys
import traceback
from pathlib import Path
import runpy
import zlib

BUNDLED_FILES = json.loads(r'''{"main.py":"","dashboard_server.py":"","CguTeam_pb2.py":"","CguFF_pb2.py":"","thunderFF_pb2.py":"","StartMatch_pb2.py":"","message_ids.py":"","templates/index.html":""}''')
ROOT = Path(__file__).resolve().parent

def _extract():
    for relative_path, encoded_content in BUNDLED_FILES.items():
        destination = (ROOT / relative_path).resolve()
        if destination != ROOT and ROOT not in destination.parents:
            raise RuntimeError(f"Invalid embedded application path: {relative_path}")
        destination.parent.mkdir(parents=True, exist_ok=True)
        decoded = zlib.decompress(base64.b64decode(encoded_content))
        temporary = destination.with_name(destination.name + f".tmp-{os.getpid()}")
        try:
            temporary.write_bytes(decoded)
            os.replace(temporary, destination)
        finally:
            try:
                if temporary.exists():
                    temporary.unlink()
            except OSError:
                pass

if __name__ == "__main__":
    try:
        print("[BOOT] extracting bundled files...", flush=True)
        _extract()
        os.chdir(ROOT)
        sys.path.insert(0, str(ROOT))
        print("[BOOT] starting main.py ...", flush=True)
        runpy.run_path(str(ROOT / "main.py"), run_name="__main__")
    except Exception:
        print("[BOOT][FATAL] Railway crash traceback:", flush=True)
        traceback.print_exc()
        sys.stdout.flush()
        sys.stderr.flush()
        raise
